export const fonts=['Arial','Verdana','Georgia','Times New Roman','Tahoma','Trebuchet MS','Calibri','Aptos','PT Sans','PT Serif','PT Mono','Roboto','Roboto Slab','Open Sans','Noto Sans','Noto Serif','Inter','Montserrat','Nunito','Rubik','Manrope','Raleway','Ubuntu','Lora','Merriweather','Oswald','Comfortaa','Fira Sans','Golos Text','IBM Plex Sans','Jost','Source Sans 3'];
export const uid=()=>crypto.randomUUID();
export function makeWord(word){let s=word.trim();let i=s.search(/[аоеия]/i);let wrong=i<0?s+'ь':s.slice(0,i)+({а:'о',о:'а',е:'и',и:'е',я:'е'}[s[i].toLowerCase()]||'а')+s.slice(i+1);return{id:uid(),word:s,wrong,hint:'',explanation:'',approved:false};}
export function initial(){let words=['берёза','молоко','собака','воробей','карандаш','тетрадь','яблоко','дорога','морковь','учитель','ребята','хорошо'].map(makeWord);return{schemaVersion:1,title:'Приключения в словарном саду',game:'garden',age:0,theme:'forest',words,objects:words.map((w,i)=>({id:uid(),wordId:w.id,x:15+(i%6)*14,y:52+Math.floor(i/6)*24,size:50,rotation:0,opacity:1,layer:1,locked:false,emoji:['🌼','🌷','🌻'][i%3]})),assets:[],font:'Arial',fontSize:30,accent:'#286b54',lives:3,timer:0,points:10,sound:false,volume:50,reduceMotion:false,titleText:'Пусть знания расцветают!',instruction:'Выбирай правильные слова и оживи волшебный сад.',winText:'Твой сад расцвёл!',loseText:'Попробуем ещё раз?',question:'Какое слово написано правильно?',updated:Date.now()};}
export function validate(p){let errors=[];if(!p.words.length)errors.push('Добавьте хотя бы одно слово.');if(p.words.some(w=>!w.word.trim()||!w.wrong.trim()||w.word.toLowerCase()===w.wrong.toLowerCase()))errors.push('У каждого задания должны быть разные правильный и ошибочный варианты.');if(p.words.some(w=>!w.approved))errors.push('Проверьте автоматически созданные варианты на вкладке «Задания».');return errors;}
export function validateProject(p){if(p?.game==='diff')p={...p,game:'safe'};if(!p||p.schemaVersion!==1||!Array.isArray(p.words)||!Array.isArray(p.objects)||!Array.isArray(p.assets)||!games.some(g=>g.id===p.game)||!themes.some(t=>t.id===p.theme))throw Error('Неподдерживаемая структура или версия проекта.');if(p.words.some(w=>typeof w.word!=='string'||typeof w.wrong!=='string'||typeof w.id!=='string'))throw Error('Повреждены записи словаря.');return p;}
export const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function parseText(text){return [...new Set(text.replace(/^\uFEFF/,'').split(/[\n;,]+/).map(s=>s.trim().replace(/^"|"$/g,'')).filter(Boolean))].map(makeWord);}
export async function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('slovnik-studio',1);r.onupgradeneeded=()=>r.result.createObjectStore('projects');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
export async function persist(p){const db=await openDB();return new Promise((res,rej)=>{let t=db.transaction('projects','readwrite');t.objectStore('projects').put(p,'current');t.oncomplete=()=>{db.close();res();};t.onerror=()=>{db.close();rej(t.error);};});}
export async function restore(){const db=await openDB();return new Promise((res,rej)=>{let r=db.transaction('projects').objectStore('projects').get('current');r.onsuccess=()=>{db.close();res(r.result);};r.onerror=()=>rej(r.error);});}
